import { PanelStateStore } from "./solution";
import type { PanelId, PanelSnapshot } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function expectTypeError(action: () => void, message: string): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  assert(thrown instanceof TypeError, message);
}

const defaults = new PanelStateStore();
const defaultSnapshot = defaults.getSnapshot();
equal(defaultSnapshot.map, false, "map defaults to false");
equal(defaultSnapshot.metrics, false, "metrics defaults to false");
equal(defaultSnapshot.notes, false, "notes defaults to false");
assert(Object.isFrozen(defaultSnapshot), "getSnapshot returns a frozen snapshot");
assert(defaultSnapshot !== defaults.getSnapshot(), "getSnapshot allocates every time");

defaults.setVisible("notes", true);
equal(defaultSnapshot.notes, false, "previous snapshots remain stable after updates");
equal(defaults.getSnapshot().notes, true, "updates work without subscribers");

expectTypeError(
  () => {
    new PanelStateStore({ map: "true" } as unknown as Partial<Record<PanelId, boolean>>);
  },
  "a string initial value is rejected"
);
expectTypeError(
  () => {
    new PanelStateStore({ metrics: undefined } as Partial<Record<PanelId, boolean>>);
  },
  "an explicitly supplied undefined initial value is rejected"
);

const initial: Partial<Record<PanelId, boolean>> = { map: true, notes: false };
const store = new PanelStateStore(initial);
initial.map = false;
equal(store.getSnapshot().map, true, "the constructor does not retain the initial object");

const events: string[] = [];
const delivered: PanelSnapshot[] = [];
let addedThird = false;
let unsubscribeSecond: () => void = () => {};

store.subscribe(snapshot => {
  events.push(`first:${snapshot.map}:${snapshot.metrics}:${snapshot.notes}`);
  delivered.push(snapshot);
  unsubscribeSecond();

  if (!addedThird) {
    addedThird = true;
    store.subscribe(later => {
      events.push(`third:${later.map}:${later.metrics}:${later.notes}`);
      delivered.push(later);
    });
  }
});

unsubscribeSecond = store.subscribe(snapshot => {
  events.push(`second:${snapshot.map}:${snapshot.metrics}:${snapshot.notes}`);
  delivered.push(snapshot);
});

equal(events.length, 0, "subscribe does not notify immediately");
store.setVisible("map", true);
equal(
  events.join("|"),
  "first:true:false:false|second:true:false:false",
  "a repeated value notifies the snapshotted listener list in subscription order"
);

const firstDelivered = delivered[0];
const secondDelivered = delivered[1];
assert(firstDelivered !== undefined && secondDelivered !== undefined, "both listeners received snapshots");
assert(firstDelivered !== secondDelivered, "each listener receives a newly allocated snapshot");
assert(Object.isFrozen(firstDelivered), "the first notification snapshot is frozen");
assert(Object.isFrozen(secondDelivered), "the second notification snapshot is frozen");

try {
  (firstDelivered as Record<PanelId, boolean>).map = false;
} catch {
  // Assignment to a frozen snapshot may throw in strict mode.
}
equal(firstDelivered.map, true, "notification snapshots cannot be mutated");
equal(store.getSnapshot().map, true, "snapshot mutation cannot affect store state");

unsubscribeSecond();
unsubscribeSecond();
store.toggle("metrics");
equal(
  events.join("|"),
  "first:true:false:false|second:true:false:false|first:true:true:false|third:true:true:false",
  "subscription changes affect later updates and unsubscribe is idempotent"
);
equal(firstDelivered.metrics, false, "earlier notification snapshots remain stable");

const current = store.getSnapshot();
equal(current.map, true, "current map state is retained");
equal(current.metrics, true, "toggle inverts the current state");
equal(current.notes, false, "an omitted panel remains false");
assert(Object.isFrozen(current), "later snapshots are frozen");
assert(current !== store.getSnapshot(), "later getSnapshot calls also allocate");

store.toggle("notes");
equal(store.getSnapshot().notes, true, "toggle works for a false panel");
store.toggle("notes");
equal(store.getSnapshot().notes, false, "toggle works repeatedly");

const failing = new PanelStateStore();
const marker = new Error("listener failure");
let afterFailureCalled = false;
failing.subscribe(() => {
  throw marker;
});
failing.subscribe(() => {
  afterFailureCalled = true;
});

let caught: unknown;
try {
  failing.setVisible("notes", true);
} catch (error) {
  caught = error;
}
assert(caught === marker, "listener exceptions propagate unchanged");
equal(afterFailureCalled, false, "a listener exception stops the notification pass");
equal(failing.getSnapshot().notes, true, "state changes before listeners are notified");

